
cc.Class({
    extends: cc.Component,

    properties: {
        _bonusId:3,
        _canTouchAddSpin: false,
    },

    Init () {
        this._bonusId = 3;

        this._mainNode = cc.find('mainnode',this.node);
        this._mainNode.active = false;

        this._topSlotsScript = cc.find('slots_top',this._mainNode).addComponent('WestCowboy_BonusSlots');
        this._bottomSlotsScript = cc.find('slots',this._mainNode).addComponent('WestCowboy_BonusSlots');
        this._topType = 1;
        this._bottomType = 2;
        this._topSlotsScript.Init(this._topType);
        this._bottomSlotsScript.Init(this._bottomType);

        this._slots_top = cc.find("slots_top", this._mainNode);
        this._slots_bottom = cc.find("slots", this._mainNode);

        if(!this._symbolTemplete){
            this._symbolTemplete = cc.vv.gameData.GetPrefabByName("symbol");
            if(this._symbolTemplete){
                this._symbolTemplete.optimizationPolicy = cc.Prefab.OptimizationPolicy.MULTI_INSTANCE
            }
        }
    },

    getWinCoin() {
        return this._winCoin;
    },

    // 断线回到bonus游戏
    async showBonusGame(bonusdata){
        return new Promise(async (success, failed) => {
            Global.SlotsSoundMgr.stopBgm();
            Global.SlotsSoundMgr.playBgm("music_ChilliFiesta_respinBgSound");
            cc.vv.gameData.setIsBonusGame(true);

            this._subGameData = bonusdata;
            // let state = bonusdata.state;
            if (this._subGameData.state === 1) { //2: spin完之后，选择额外spin次数
                await this.showBonusGameUI();

                await this.addSpins();
                // this._subGameData = cc.vv.gameData.getBonusGame();

                this._curCnt = this._subGameData.totalSpinCnt - this._subGameData.spinCnt;
                this._totalCnt = this._subGameData.totalSpinCnt;

            } else if (this._subGameData.state === 0) { //0: 正常bonus游戏,
                await this.showBonusGameUI();
            }

            // 开始旋转
            this.reqSpine();

            this._callBack = success;
        })
    },

    // 结束bonus游戏
    async endBonusGame(){
        console.log('###bonus游戏结束');
        let result_node = cc.find("result_node", this._mainNode);
        result_node.active = true;
        cc.vv.AudioManager.playEff("games/WestCowboy/", "music_ChilliFiesta_respinOver", true);
        let winCoin = cc.find("winCoin", result_node);
        winCoin.getComponent(cc.Label).string = "0";

        await this.collectSlotsCoin();

        await cc.vv.gameData.awaitTime(2);

        await this.popResultDialog();

        if(this._callBack){
            Global.SlotsSoundMgr.stopBgm();
            cc.vv.gameData.setIsBonusGame(false);
            this._winCoin = this._subGameData.winCoin;
            this._callBack();
            this._callBack = null;
            this._subGameData = null;
        }
    },

    async popResultDialog() {
        return new Promise(async (success) => {
            cc.vv.AudioManager.playEff("games/WestCowboy/", "music_ChilliFiesta_freespinOver", true);
            let free_dialog = cc.find("free_dialog", this.node.parent);
            free_dialog.active = true;

            let dialog = cc.find("bonus_result_node", free_dialog);
            dialog.active = true;

            let bg = cc.find("bg", dialog);
            bg.scale = 0;
            cc.tween(bg)
                .to(0.5, {scale: 1}, {easing: "backOut"})
                .start();

            let coin = cc.find("coin", bg);
            coin.getComponent(cc.Label).string = Global.formatMoney(this._subGameData.winCoin);

            let btn_collect = cc.find("btn_collect", bg);
            btn_collect.off("click");
            let func = async ()=>{
                btn_collect.off("click");
                cc.vv.AudioManager.playEff("games/WestCowboy/", "music_ChilliFiesta_collect", true);
                // cc.vv.AudioManager.playEff("games/StoneAgedTreasure/", "click", true);
                // cc.vv.AudioManager.playEff("games/StoneAgedTreasure/", "dialog_retract", true);

                cc.tween(bg)
                    .to(0.5, {scale: 0}, {easing: "backIn"})
                    .call(() => {
                        dialog.active = false;
                        free_dialog.active = false;
                        success();
                    })
                    .start()
            }
            cc.vv.gameData.checkAutoPlay(btn_collect, func);
            btn_collect.on("click", async () => {
                btn_collect.stopAllActions();
                await func();
            });
        })
    },

    // 显示bonus游戏
    async showBonusGameUI( ){
        return new Promise(async(success, failed)=>{
            this._mainNode.active = true;
            let result_node = cc.find("result_node", this._mainNode);
            result_node.active = false;
            // this.lockJackpot(this._subGameData.jackpotValues);

            this._totalCnt = this._subGameData.totalSpinCnt;
            this._curCnt = this._subGameData.totalSpinCnt - this._subGameData.spinCnt;
            cc.find("spin/curTimes", this._mainNode).getComponent(cc.Label).string = this._curCnt;
            cc.find("spin/allTimes", this._mainNode).getComponent(cc.Label).string = this._totalCnt;

            await this.showBonusSlotsUI();

            success();
        })
    },

    // 初始显示slots
    async showBonusSlotsUI(){
        return new Promise(async(success, failed) => {
            this._bottomSlotsScript.initAllSymbol();
            this._topSlotsScript.initAllSymbol();

            if (this._curCnt === 0) {
                cc.find("repeater_feature_prize/coin", this._mainNode).getComponent(cc.Label).string = "";
                let bonusIdxs = this._subGameData.slots[0].bonusIdxs;
                let bonusItems = this._subGameData.slots[0].bonusItems;
                for (let i = 0; i < bonusIdxs.length; i++) {
                    let symbol = this._bottomSlotsScript.GetSymbolByIdx(bonusIdxs[i]);
                    let data = bonusItems[i];
                    symbol.ShowById(cc.vv.gameData.getGameCfg().bonusId, data);
                    symbol.playBonusStopAnimation();
                }

                await cc.vv.gameData.awaitTime(2);

                let coin = 0;
                for (let i = 0; i < bonusIdxs.length; i++) {
                    let symbol = this._bottomSlotsScript.GetSymbolByIdx(bonusIdxs[i]);
                    let data = bonusItems[i];
                    if (data.coin) {
                        coin += data.coin;
                    } else if (data.jackpot) {
                        coin += data.jackpot.value;
                    }

                    let startPos = symbol.node.convertToWorldSpaceAR(cc.v2(0, 0));
                    startPos = this.node.parent.convertToNodeSpaceAR(startPos);
                    let endPos = cc.find("repeater_feature_prize/coin", this._mainNode).convertToWorldSpaceAR(cc.v2(0, 0));
                    endPos = this.node.parent.convertToNodeSpaceAR(endPos);
                    cc.vv.AudioManager.playEff("games/WestCowboy/", "music_ChilliFiesta_respinBonusCollect", true);
                    let particle = cc.instantiate(cc.find("fly_particle", this.node.parent));
                    particle.parent = this.node.parent;
                    particle.position = startPos;
                    particle.active = true;
                    cc.tween(particle)
                        .to(0.5, {position: endPos})
                        .call(()=>{
                            cc.find("repeater_feature_prize/coin", this._mainNode).getComponent(cc.Label).string =
                                Global.formatMoney(coin);

                            cc.vv.AudioManager.playEff("games/WestCowboy/", "music_ChilliFiesta_bonusCollectBuling", true);
                            let effect = cc.instantiate(cc.find("repeater_feature_prize_particle", this.node.parent));
                            effect.parent = this.node.parent;
                            effect.position = endPos;
                            effect.active = true;

                            cc.tween(effect)
                                .delay(0.5)
                                .removeSelf()
                                .start();

                            particle.removeFromParent();
                        })
                        .start();

                    await cc.vv.gameData.awaitTime(0.5);
                }

                for (let i = 0; i < bonusIdxs.length; i++) {
                    let symbol = this._bottomSlotsScript.GetSymbolByIdx(bonusIdxs[i]);
                    let data = bonusItems[i];
                    let startPos = symbol.node.convertToWorldSpaceAR(cc.v2(0, 0));
                    startPos = this.node.parent.convertToNodeSpaceAR(startPos);
                    let endSymbol = this._topSlotsScript.GetSymbolByIdx(bonusIdxs[i]);
                    let endPos = endSymbol.node.convertToWorldSpaceAR(cc.v2(0, 0));
                    endPos = this.node.parent.convertToNodeSpaceAR(endPos);

                    cc.vv.AudioManager.playEff("games/WestCowboy/", "music_ChilliFiesta_respinBonusUpFly", true);
                    let sprite = cc.instantiate(cc.find("lajiao_sprite", this.node.parent));
                    sprite.parent = this.node.parent;
                    sprite.position = startPos;
                    sprite.active = true;
                    cc.tween(sprite)
                        .parallel(
                            cc.tween().to(0.25, {scale: 2}).to(0.25, {scale: 1}),
                            cc.tween().to(0.5, {position: endPos})
                        )
                        .call(()=>{
                            cc.vv.AudioManager.playEff("games/WestCowboy/", "music_ChilliFiesta_respinBonusUpBuling", true);
                            let effect = cc.instantiate(cc.find("effect_ljlr_baopo", this.node.parent));
                            effect.parent = this.node.parent;
                            effect.position = endPos;
                            effect.active = true;

                            cc.tween(effect)
                                .delay(0.5)
                                .removeSelf()
                                .start();

                            endSymbol.ShowById(cc.vv.gameData.getGameCfg().bonusId, data);
                            endSymbol.playBonusGenerateAnimation();
                        })
                        .removeSelf()
                        .start();

                    await cc.vv.gameData.awaitTime(0.5);
                }

                success();
            } else {
                let bonusIdxs = this._subGameData.slots[0].bonusIdxs;
                let bonusItems = this._subGameData.slots[0].bonusItems;
                for (let i = 0; i < 15; i++) {
                    let symbol = this._bottomSlotsScript.GetSymbolByIdx(i + 1);
                    if (bonusIdxs.indexOf(i + 1) !== -1) {
                        let data = bonusItems[bonusIdxs.indexOf(i + 1)];
                        symbol.ShowById(cc.vv.gameData.getGameCfg().bonusId, data);
                        symbol.playBonusStopAnimation();
                    } else {
                        symbol.ShowRandomSymbol();
                    }
                }
                // for (let i = 0; i < bonusIdxs.length; i++) {
                //     let symbol = this._bottomSlotsScript.GetSymbolByIdx(bonusIdxs[i]);
                //     let data = bonusItems[i];
                //     symbol.ShowById(cc.vv.gameData.getGameCfg().bonusId, data);
                //     symbol.playBonusStopAnimation();
                // }

                bonusIdxs = this._subGameData.slots[1].bonusIdxs;
                bonusItems = this._subGameData.slots[1].bonusItems;
                for (let i = 0; i < 15; i++) {
                    let symbol = this._topSlotsScript.GetSymbolByIdx(i + 1);
                    if (bonusIdxs.indexOf(i + 1) !== -1) {
                        let data = bonusItems[bonusIdxs.indexOf(i + 1)];
                        symbol.ShowById(cc.vv.gameData.getGameCfg().bonusId, data);
                        symbol.playBonusStopAnimation();
                    } else {
                        symbol.ShowRandomSymbol();
                    }
                }

                cc.find("repeater_feature_prize/coin", this._mainNode).getComponent(cc.Label).string =
                    Global.formatMoney(this._subGameData.baseCoin);

                success();
            }
        });
    },

    //收集按slots从上到下收集
    async collectSlotsCoin(){
        return new Promise(async(success)=>{
            let coin = 0;
            for (let i = 0; i < this._subGameData.slots.length; i++) {
                let slot = this._subGameData.slots[i];
                let script = i === 0 ? this._topSlotsScript : this._bottomSlotsScript;
                let endPos = cc.find("result_node/winCoin", this._mainNode).convertToWorldSpaceAR(cc.v2(0, 0));
                endPos = this.node.parent.convertToNodeSpaceAR(endPos);
                for (let j = 0; j < 15; j++) {
                    let symbol = script.GetSymbolByIdx(j + 1);
                    if (symbol.GetShowId() !== cc.vv.gameData.getGameCfg().bonusId) {
                        continue;
                    }
                    let startPos = symbol.node.convertToWorldSpaceAR(cc.v2(0, 0));
                    startPos = this.node.parent.convertToNodeSpaceAR(startPos);
                    cc.vv.AudioManager.playEff("games/WestCowboy/", "music_ChilliFiesta_respinBonusCollect", true);
                    let particle = cc.instantiate(cc.find("fly_particle", this.node.parent));
                    particle.parent = this.node.parent;
                    particle.position = startPos;
                    particle.active = true;
                    cc.tween(particle)
                        .to(0.5, {position: endPos})
                        .call(()=>{
                            if (symbol.GetData().baseCoin) {
                                coin += symbol.GetData().baseCoin;
                            } else if (symbol.GetData().jackpot) {
                                coin += symbol.GetData().jackpot.value;
                            } else {
                                coin += symbol.GetData().coin;
                            }

                            cc.find("result_node/winCoin", this._mainNode).getComponent(cc.Label).string =
                                Global.formatMoney(coin);

                            cc.vv.AudioManager.playEff("games/WestCowboy/", "music_ChilliFiesta_bonusCollectBuling", true);
                            let effect = cc.instantiate(cc.find("repeater_feature_prize_particle", this.node.parent));
                            effect.parent = this.node.parent;
                            effect.position = endPos;
                            effect.active = true;
                            cc.tween(effect)
                                .delay(0.5)
                                .removeSelf()
                                .start();

                            particle.removeFromParent();
                        })
                        .start();

                    await cc.vv.gameData.awaitTime(0.5);
                }
            }
            success();
        })
    },

    //奖池锁定(停止滚动)
    lockJackpot(jackpotvalus){
        let prizepool = cc.find('LMSlots_PrizePool2',this._mainNode).getComponent("LMSlots_PrizePool_Base");
        prizepool.PausePool([{prizeType:0,pauseNum:jackpotvalus[0]},{prizeType:1,pauseNum:jackpotvalus[1]},
            {prizeType:2,pauseNum:jackpotvalus[2]},{prizeType:3,pauseNum:jackpotvalus[3]},{prizeType:4,pauseNum:jackpotvalus[4]}]);
    },


    //点击开始移动
    startSpin(){

    },

    //显示结果
    showSpinResult(){

    },

    //返回51请求结果
    getSubGameData(){
        return this._subGameData;
    },

    //旋转停止
    spinEnd(){
        
    },

    // OnReelSpinEnd(colIdx){
        // this._bottomSlotsScript.OnSlotsSpinEnd(colIdx);
        // this._topSlotsScript.OnSlotsSpinEnd(colIdx);
    // },

    //bonus游戏旋转结果请求
    async reqSpine(){
        cc.log(cc.js.formatStr("startMove:%s, %s", this._curCnt, this._totalCnt));

        this._curCnt += 1
        cc.find("spin/curTimes", this._mainNode).getComponent(cc.Label).string = this._curCnt;
        cc.find("spin/allTimes", this._mainNode).getComponent(cc.Label).string = this._totalCnt;
        this._topSlotsScript.StartMove(this._subGameData.slots[0].bonusIdxs);
        this._bottomSlotsScript.StartMove(this._subGameData.slots[1].bonusIdxs);

        await cc.vv.gameData.awaitTime(1);
        let reqdata = {rtype:3};
        let result = await cc.vv.gameData.reqSubGame(reqdata);
        if(result.code === 200 && !result.spcode){
            this._subGameData = result.data.bonusGame;
            // cc.vv.gameData.setBonusGame(this._subGameData);

            this._bottomSlotsScript.setSpinResult(this._subGameData.slots[1].bonusIdxs, this._subGameData.slots[1].bonusItems);
            this._topSlotsScript.setSpinResult(this._subGameData.slots[0].bonusIdxs, this._subGameData.slots[0].bonusItems);
        }
    },

    //点击停止按钮调用
    StopMove:function(){
        this._topSlotsScript.StopMove();
        this._bottomSlotsScript.StopMove();
    },

    async OnSpinEnd(){
        cc.log("OnSpinEnd")

        // let bonusdata = cc.vv.gameData.getBonusGame();
        cc.vv.gameData.GetBottomScript().ShowBtnsByState("moveing_1");
        // this.bonusGameHandle(bonusdata);

        await this.triggerGetGoldLajiao();

        if(this._subGameData.state === 1){
            //state未表示需要添加spin界面
            await this.addSpins();

            this._curCnt = this._subGameData.totalSpinCnt - this._subGameData.spinCnt;
            this._totalCnt = this._subGameData.totalSpinCnt;
            this.reqSpine();
        }else{
            //此处进入bonus游戏后 不会调用
            if(this._subGameData.spinCnt > 0){
                await cc.vv.gameData.awaitTime(1);
                this.reqSpine();
            }else{
               this.endBonusGame();
            }
        }
    },

    async addSpins() {
        return new Promise(async (success)=>{
            cc.vv.AudioManager.playEff("games/WestCowboy/", "music_ChilliFiesta_respinChoose", true);

            let add_spin_node = cc.find("add_spin_node", this._mainNode);
            add_spin_node.active = true;
            let mainnode = cc.find("mainnode", add_spin_node);
            mainnode.scale = 0;
            mainnode.active = true;
            cc.tween(mainnode)
                .to(0.5, {scale: 1}, {easing: "backOut"})
                .call(()=>{
                    this._canTouchAddSpin = true;
                    this.playAnimationOnce(cc.find("kuang_animation", mainnode), "saoguang5");
                    this.playAnimationOnce(cc.find("headtext2/idle", mainnode), "saoguang6");
                    for (let i = 1; i < 4; i++) {
                        this.playAnimationOnce(cc.find("number" + i + "/idle", mainnode), "saoguang3");
                    }
                })
                .start();

            for (let i = 1; i < 4; i++) {
                let number = cc.find("number" + i, mainnode);
                cc.find("num", number).active = false;
                cc.find("wenhao", number).active = true;
                cc.find("spin", number).active = false;
                cc.find("disable", number).active = false;

                number.off(cc.Node.EventType.TOUCH_END);
                number.on(cc.Node.EventType.TOUCH_END, async ()=>{
                    if (!this._canTouchAddSpin) {
                        return;
                    }

                    mainnode.stopAllActions();
                    this._canTouchAddSpin = false;
                    cc.vv.AudioManager.playEff("games/WestCowboy/", "music_ChilliFiesta_respinChooseClick", true);
                    let reqdata = {rtype:2,choiceId:i};
                    let result = await cc.vv.gameData.reqSubGame(reqdata);
                    if (result.code === 200 && result.data.rtype === 2) {
                        this._subGameData = result.data.bonusGame;
                        let selectNumber = cc.find("number" + result.data.choiceId, mainnode);
                        let atlas = cc.vv.gameData.GetAtlasByName("ChilliFiesta2");
                        cc.find("num", selectNumber).active = true;
                        cc.find("num", selectNumber).getComponent(cc.Sprite).spriteFrame =
                            atlas.getSpriteFrame("ChilliFiesta-Common-ChiliFiesta_respin_" + result.data.extraSpins[result.data.choiceId - 1]);
                        cc.find("spin", selectNumber).active = true;
                        cc.find("spin", selectNumber).getComponent(cc.Sprite).spriteFrame =
                            atlas.getSpriteFrame(result.data.extraSpins[result.data.choiceId - 1] > 1
                                ? "ChilliFiesta-Common-ChiliFiesta_respin_spins"
                                : "ChilliFiesta-Common-ChiliFiesta_respin_spin");
                        cc.find("wenhao", selectNumber).active = false;

                        this.playAnimationOnce(cc.find("select", selectNumber), "saoguang7");

                        await cc.vv.gameData.awaitTime(0.5);

                        for (let j = 1; j < 4; j++) {
                            if (j !== result.data.choiceId) {
                                let unselectNumber = cc.find("number" + j, mainnode);
                                cc.find("disable", unselectNumber).active = false;
                                let atlas = cc.vv.gameData.GetAtlasByName("ChilliFiesta2");
                                cc.find("num", unselectNumber).active = true;
                                cc.find("num", unselectNumber).getComponent(cc.Sprite).spriteFrame =
                                    atlas.getSpriteFrame("ChilliFiesta-Common-ChiliFiesta_respin_"
                                        + result.data.extraSpins[j - 1]
                                        + "" + result.data.extraSpins[j - 1]);
                                cc.find("spin", unselectNumber).active = true;
                                cc.find("spin", unselectNumber).getComponent(cc.Sprite).spriteFrame =
                                    atlas.getSpriteFrame(result.data.extraSpins[j - 1] > 1
                                        ? "ChilliFiesta-Common-ChiliFiesta_respin_spinsUn2"
                                        : "ChilliFiesta-Common-ChiliFiesta_respin_spinUn2");
                                cc.find("wenhao", unselectNumber).active = false;

                                this.playAnimationOnce(cc.find("select", unselectNumber), "saoguang7");
                            }
                        }

                        await cc.vv.gameData.awaitTime(1);

                        cc.tween(mainnode)
                            .to(0.5, {scale: 0}, {easing: "backIn"})
                            .call(()=>{
                                add_spin_node.active = false;
                                success();
                            })
                            .start();
                    }
                });
            }

            await cc.vv.gameData.awaitTime(0.5);
            if (cc.vv.gameData.isNeedAutoPlay()) {
                cc.tween(mainnode)
                    .delay(cc.vv.gameData.getManualAutoPlayTime())
                    .call(async ()=>{
                        if (!this._canTouchAddSpin) {
                            return;
                        }

                        this._canTouchAddSpin = false;
                        cc.vv.AudioManager.playEff("games/WestCowboy/", "music_ChilliFiesta_respinChooseClick", true);
                        let reqdata = {rtype:2,choiceId:1};
                        let result = await cc.vv.gameData.reqSubGame(reqdata);
                        if (result.code === 200 && result.data.rtype === 2) {
                            this._subGameData = result.data.bonusGame;
                            let selectNumber = cc.find("number" + result.data.choiceId, mainnode);
                            let atlas = cc.vv.gameData.GetAtlasByName("ChilliFiesta2");
                            cc.find("num", selectNumber).active = true;
                            cc.find("num", selectNumber).getComponent(cc.Sprite).spriteFrame =
                                atlas.getSpriteFrame("ChilliFiesta-Common-ChiliFiesta_respin_" + result.data.extraSpins[result.data.choiceId - 1]);
                            cc.find("spin", selectNumber).active = true;
                            cc.find("spin", selectNumber).getComponent(cc.Sprite).spriteFrame =
                                atlas.getSpriteFrame(result.data.extraSpins[result.data.choiceId - 1] > 1
                                    ? "ChilliFiesta-Common-ChiliFiesta_respin_spins"
                                    : "ChilliFiesta-Common-ChiliFiesta_respin_spin");
                            cc.find("wenhao", selectNumber).active = false;

                            this.playAnimationOnce(cc.find("select", selectNumber), "saoguang7");

                            await cc.vv.gameData.awaitTime(0.5);

                            for (let j = 1; j < 4; j++) {
                                if (j !== result.data.choiceId) {
                                    let unselectNumber = cc.find("number" + j, mainnode);
                                    cc.find("disable", unselectNumber).active = false;
                                    let atlas = cc.vv.gameData.GetAtlasByName("ChilliFiesta2");
                                    cc.find("num", unselectNumber).active = true;
                                    cc.find("num", unselectNumber).getComponent(cc.Sprite).spriteFrame =
                                        atlas.getSpriteFrame("ChilliFiesta-Common-ChiliFiesta_respin_"
                                            + result.data.extraSpins[j - 1]
                                            + "" + result.data.extraSpins[j - 1]);
                                    cc.find("spin", unselectNumber).active = true;
                                    cc.find("spin", unselectNumber).getComponent(cc.Sprite).spriteFrame =
                                        atlas.getSpriteFrame(result.data.extraSpins[j - 1] > 1
                                            ? "ChilliFiesta-Common-ChiliFiesta_respin_spinsUn2"
                                            : "ChilliFiesta-Common-ChiliFiesta_respin_spinUn2");
                                    cc.find("wenhao", unselectNumber).active = false;

                                    this.playAnimationOnce(cc.find("select", unselectNumber), "saoguang7");
                                }
                            }

                            await cc.vv.gameData.awaitTime(1);

                            cc.tween(mainnode)
                                .to(0.5, {scale: 0}, {easing: "backIn"})
                                .call(()=>{
                                    add_spin_node.active = false;
                                    success();
                                })
                                .start();
                        }
                    })
                    .start();
            }
        });
    },

    playAnimationOnce(node, animationName, callback) {
        node.active = true;
        if (animationName) {
            node.getComponent(cc.Animation).play(animationName);
        } else {
            node.getComponent(cc.Animation).play();
        }

        node.getComponent(cc.Animation).on("stop", ()=>{
            node.getComponent(cc.Animation).off("stop");
            node.active = false;
            if (callback) {
                callback();
            }
        });
    },

    async triggerGetGoldLajiao() {
        return new Promise(async (success)=>{
            let topSlot = this._subGameData.slots[0];
            for (let bonusItem of topSlot.bonusItems) {
                if (bonusItem.baseCoin) {
                    let idx = topSlot.bonusIdxs[topSlot.bonusItems.indexOf(bonusItem)];
                    let symbol = this._topSlotsScript.GetSymbolByIdx(idx);

                    let trigger = cc.find("repeater_feature_prize/trigger", this._mainNode);
                    trigger.active = true;
                    trigger.getComponent(cc.Animation).play("freespinsj");
                    trigger.getComponent(cc.Animation).on("stop", ()=>{
                        trigger.getComponent(cc.Animation).off("stop");
                        trigger.active = false;
                    });

                    let startPos = cc.find("repeater_feature_prize/coin", this._mainNode).convertToWorldSpaceAR(cc.v2(0, 0));
                    startPos = this.node.parent.convertToNodeSpaceAR(startPos);
                    let endPos = symbol.node.convertToWorldSpaceAR(cc.v2(0, 0));
                    endPos = this.node.parent.convertToNodeSpaceAR(endPos);

                    cc.vv.AudioManager.playEff("games/WestCowboy/", "music_ChilliFiesta_respinBonusCollect", true);
                    let particle = cc.instantiate(cc.find("fly_particle", this.node.parent));
                    particle.parent = this.node.parent;
                    particle.position = startPos;
                    particle.active = true;
                    cc.tween(particle)
                        .to(0.5, {position: endPos})
                        .call(()=>{
                            symbol.playBonusCoinAnimation();
                            particle.removeFromParent();
                        })
                        .start();

                    await cc.vv.gameData.awaitTime(0.5);
                }
            }

            let bottomSlot = this._subGameData.slots[0];
            for (let bonusItem of bottomSlot.bonusItems) {
                if (bonusItem.baseCoin) {
                    let idx = bottomSlot.bonusIdxs[bottomSlot.bonusItems.indexOf(bonusItem)];
                    let symbol = this._bottomSlotsScript.GetSymbolByIdx(idx);

                    let trigger = cc.find("repeater_feature_prize/trigger", this._mainNode);
                    trigger.active = true;
                    trigger.getComponent(cc.Animation).play("freespinsj");
                    trigger.getComponent(cc.Animation).on("stop", ()=>{
                        trigger.getComponent(cc.Animation).off("stop");
                        trigger.active = false;
                    });

                    let startPos = cc.find("repeater_feature_prize/coin", this._mainNode).convertToWorldSpaceAR(cc.v2(0, 0));
                    startPos = this.node.parent.convertToNodeSpaceAR(startPos);
                    let endPos = symbol.node.convertToWorldSpaceAR(cc.v2(0, 0));
                    endPos = this.node.parent.convertToNodeSpaceAR(endPos);

                    cc.vv.AudioManager.playEff("games/WestCowboy/", "music_ChilliFiesta_respinBonusCollect", true);
                    let particle = cc.instantiate(cc.find("fly_particle", this.node.parent));
                    particle.parent = this.node.parent;
                    particle.position = startPos;
                    particle.active = true;
                    cc.tween(particle)
                        .to(0.5, {position: endPos})
                        .call(()=>{
                            cc.vv.AudioManager.playEff("games/WestCowboy/", "music_ChilliFiesta_bonus_buling", true);
                            symbol.playBonusCoinAnimation();
                            particle.removeFromParent();
                        })
                        .start();

                    await cc.vv.gameData.awaitTime(0.5);
                }
            }

            success();
        });
    },

    // 获取最后停止的列和卷轴
    GetLastStopSlotReel(){
        let topEndIdx = this._topSlotsScript.GetLastStopReelIdx();
        let bottomEndIdx = this._bottomSlotsScript.GetLastStopReelIdx();

        let lastIdx = bottomEndIdx ? bottomEndIdx : topEndIdx;
        let stopType = bottomEndIdx ? this._bottomType : this._topType;

        return {slotType:stopType, reelIdx:lastIdx};
    },

    getMaxReelIdx(type, col){
        let reelList = type === this._topType ? this._topSlotsScript.getLastStopReel() : this._bottomSlotsScript.getLastStopReel();
        return reelList[col];
    },
});
