cc.Class({
    extends: require("LMSlots_Reel_Base"),

    properties: {

    },

    //旋转
    StartMove:function(){
        this._super();
    },

    //列停止
    OnReelSpinEnd:function(){
        this._super();
    },

    playReelStop() {
        this._super();

        let haveBonus = false;
        if (this._originResult) {
            for(let i = 0; i < this._originResult.length; i++){
                let item = this._symbols[i]
                if (item.GetShowId() === this._cfg.bonusId) {
                    haveBonus = true;
                    item.playBonusStopAnimation();
                }
            }
        }

        if (haveBonus) {
            cc.vv.AudioManager.playEff("games/WestCowboy/", "music_ChilliFiesta_baseBonusBuling", true);
        }
    },
});