/**
 * @description
 */

cc.Class({
    extends: require("LMSlots_Slots_Base"),

    properties: {
        _enterFreeCallback: null,
    },

    Init() {
        this._super();
    },


    //点击旋转按钮调用
    StartMove: function () {
        if(cc.vv.gameData.isBonusGame()){
            return
        }

        this._super();

        Global.SlotsSoundMgr.playNormalBgm();

        cc.find("rate_tips/rate", this.node).getComponent(cc.Label).string = "";
        cc.find("free_tips/allTimes", this.node).getComponent(cc.Label).string = cc.vv.gameData.GetTotalFree();
        cc.find("free_tips/curTimes", this.node).getComponent(cc.Label).string = cc.vv.gameData.GetTotalFree() - cc.vv.gameData.GetFreeTime();
    },

    async ReconnectShow() {
        // this._super();

        let deskInfo = cc.vv.gameData.getDeskInfo();
        if (deskInfo.extraFreeInfo) {
            this._bottomScript.ShowBtnsByState("moveing_1");
            if (deskInfo.extraFreeInfo.state === 0) {
                await this.popFreeDialog(deskInfo.extraFreeInfo);

                this.cutSceneChili();

                await cc.vv.gameData.awaitTime(1);
            }

            if (deskInfo.extraFreeInfo.state === 1) {
                cc.find("free_tips/allTimes", this.node).getComponent(cc.Label).string = cc.vv.gameData.GetTotalFree();
                cc.find("free_tips/curTimes", this.node).getComponent(cc.Label).string = cc.vv.gameData.GetTotalFree() - cc.vv.gameData.GetFreeTime();
            }

            cc.find("rate_tips/rate", this.node).getComponent(cc.Label).string = "";

            cc.find("free_dialog/common_enter_node", this.node.parent).active = false;
            cc.find("free_dialog", this.node.parent).active = false;
            this.ShowGameview(true);

            // 触发免费游戏
            await cc.vv.gameData.awaitTime(2);

            Global.SlotsSoundMgr.stopBgm();
            Global.SlotsSoundMgr.playBgm("music_ChilliFiesta_freeSpinBgSound");
            this.CanDoNextRound();
        } else if (deskInfo.bonusGame) {
            this._bottomScript.ShowBtnsByState("moveing_1");
            await cc.vv.gameData.getBonusGameMgr().showBonusGame(deskInfo.bonusGame);

            this.cutSceneChili();

            await cc.vv.gameData.awaitTime(1);

            cc.vv.gameData.getBonusGameMgr()._mainNode.active = false;

            await cc.vv.gameData.awaitTime(1);

            this.ShowBottomWin(cc.vv.gameData.getBonusGameMgr().getWinCoin(), cc.vv.gameData.getBonusGameMgr().getWinCoin(), true, ()=>{
                this.CanDoNextRound();
            });
        } else {
            this.CanDoNextRound();
        }
    },

    StopMove:function(){
        if(cc.vv.gameData.isBonusGame()){
            cc.vv.gameData.getBonusGameMgr().StopMove();
            return;
        }

        this._super()
    },

    async onMsgSpine(msg) {
        this._super(msg);
    },

    SetSlotsResult: function (cards) {
        let acRow = cards.length / this._col
        let reelResults = []
        for (let i = 0; i < cards.length; i++) {
            let row = Math.floor(i / acRow)
            let col = i % this._col
            //配置中有没有这个元素
            if (this._cfg.symbol[cards[i]]) {
                let res = {}
                res.sid = cards[i] //符号id
                if (cards[i] === this._cfg.bonusId) {
                    let index = this._gameInfo.bonusIdxs.indexOf(i + 1);
                    if (index !== -1 && index < this._gameInfo.bonusItems.length) {
                        res.data = this._gameInfo.bonusItems[index];
                    }
                }
                if (!reelResults[col]) reelResults[col] = []
                reelResults[col].unshift(res)
            }
        }

        for (let i = 0; i < this._reels.length; i++) {
            let item = this._reels[i]
            let reelRes = reelResults[i]
            item.SetResult(reelRes)
        }
    },

    //检查进入免费
    CheckEnterFreeGame: function () {
        return this._gameInfo.extraFreeInfo && this._gameInfo.extraFreeInfo.state === 0;
    },

    CheckExitFreeGame() {
        return cc.vv.gameData.GetTotalFree() > 0 && cc.vv.gameData.GetFreeTime() === 0;
    },

    //显示中奖路线
    //竞品中的显示线路是：先总，后单条循环。目前我们只显示总的
    ShowWinTrace: function () {
        this._super();
    },

    cutSceneChili() {
        cc.vv.AudioManager.playEff("games/WestCowboy/", "music_ChilliFiesta_respinChangeScene", true);
        let transition = cc.find("ChilliFiesta_guochang", this.node.parent);
        transition.active = true;
        let spine = transition.getComponent(sp.Skeleton);
        spine.setAnimation(0, "skill", false);
        spine.setCompleteListener(() => {
            spine.setCompleteListener(null);
            transition.active = false;
        });
    },

    //重写：显示bonus中奖
    async OnSpinEnd() {
        if (cc.vv.gameData.GetTotalFree() > 0 && cc.vv.gameData.GetTotalFree() !== cc.vv.gameData.GetFreeTime()) {
            // 免费中
            await this.showFreeRate();
        }

        this.ShowWinTrace();

        let winCoin = cc.vv.gameData.GetGameWin();
        let totalWinCoin = cc.vv.gameData.GetGameWin();
        if (cc.vv.gameData.GetTotalFree() > 0 && cc.vv.gameData.GetTotalFree() !== cc.vv.gameData.GetFreeTime()) {
            // 免费中
            totalWinCoin = cc.vv.gameData.GetGameTotalFreeWin();
        }

        this.ShowBottomWin(winCoin, totalWinCoin, true, async () => {
            if (this._gameInfo.bonusGame) {
                this.triggerBonusGame();
            } else if (this.CheckEnterFreeGame()) {
                this.triggerFreeGame();
            } else if (this.CheckExtraFreeGame()) {
                this.triggerExtraFreeGame();
            } else {
                if (this.CheckExitFreeGame()) {
                    this.triggerExitFreeGame();
                } else {
                    this.CanDoNextRound();
                }
            }

        });
    },

    CheckExtraFreeGame() {
        return !!(this._gameInfo.freeResult && this._gameInfo.freeResult.freeInfo && this._gameInfo.freeResult.freeInfo.freeCnt > 0);
    },

    async triggerBonusGame() {
        cc.vv.AudioManager.playEff("games/WestCowboy/", "music_ChilliFiesta_respinTrigger", true);
        let logo = cc.find("ChilliFiesta_logo", this.node.parent);
        logo.getComponent(sp.Skeleton).setAnimation(0, "skill", false);
        logo.getComponent(sp.Skeleton).addAnimation(0, "idle", true);

        for (let i = 0; i < this._gameInfo.bonusIdxs.length; i++) {
            let symbol = this.GetSymbolByIdx(this._gameInfo.bonusIdxs[i]);
            if (symbol) {
                symbol.playBonusTriggerAnimation();
            }
        }

        await cc.vv.gameData.awaitTime(4);

        this.cutSceneChili();

        await cc.vv.gameData.awaitTime(1);

        await cc.vv.gameData.getBonusGameMgr().showBonusGame(this._gameInfo.bonusGame);

        this.cutSceneChili();

        await cc.vv.gameData.awaitTime(1);

        cc.vv.gameData.getBonusGameMgr()._mainNode.active = false;

        await cc.vv.gameData.awaitTime(1);

        this.ShowBottomWin(cc.vv.gameData.getBonusGameMgr().getWinCoin(), cc.vv.gameData.getBonusGameMgr().getWinCoin(), true, ()=>{
            this.CanDoNextRound();
        });
    },

    async triggerExtraFreeGame() {
        this._bottomScript.ShowBtnsByState("moveing_1");
        cc.vv.AudioManager.playEff("games/WestCowboy/", "music_ChilliFiesta_scatterTrigger", true);
        for (let i = 0; i < this._gameInfo.resultCards.length; i++) {
            let card = this._gameInfo.resultCards[i];
            if (card === this._cfg.scatterId) {
                let symbol = this.GetSymbolByIdx(i + 1);
                symbol.playWinAnimation();
            }
        }

        // cc.vv.AudioManager.playEff("games/MammothGrand/", "fg_bell", true);

        await cc.vv.gameData.awaitTime(2);

        await this.popExtraFreeDialog();

        await cc.vv.gameData.awaitTime(1);

        this.CanDoNextRound();
    },

    async popExtraFreeDialog() {
        cc.vv.AudioManager.playEff("games/WestCowboy/", "music_ChilliFiesta_freespinmore", true);
        let free_dialog = cc.find("free_dialog", this.node.parent);
        free_dialog.active = true;

        let dialog = cc.find("extra_node", free_dialog);
        dialog.active = true;

        cc.find("bg/times", dialog).getComponent(cc.Label).string = this._gameInfo.freeResult.freeInfo.freeCnt;

        await cc.vv.gameData.awaitTime(2);

        dialog.active = false;
        free_dialog.active = false;
    },

    async showFreeRate() {
        return new Promise((success) => {
            if (this._gameInfo.extraFreeInfo && this._gameInfo.extraFreeInfo.currMult) {
                cc.find("rate_tips/rate", this.node).getComponent(cc.Label).string = "X" + this._gameInfo.extraFreeInfo.currMult;
                cc.vv.AudioManager.playEff("games/WestCowboy/", "music_ChilliFiesta_wildFire", true);
                let baodian = cc.find("rate_tips/baodian", this.node);
                baodian.active = true;
                baodian.getComponent(cc.Animation).play("firebaodian");
                // baodian.getComponent(cc.Animation).finished()
                baodian.getComponent(cc.Animation).on("stop", () => {
                    success();
                    baodian.active = false;
                });
            } else {
                success();
            }
        });
    },


    //显示游戏界面：bFree true显示免费模式的界面，false 普通模式
    ShowGameview: function (bFree) {
        this._super(bFree);

        for (let i = 0; i < 5; i++) {
            let freebg = cc.find("reels_bg/reel_bg" + (i + 1) + "/free", this.node);
            freebg.active = bFree;
        }

        cc.find("free_tips", this.node).active = bFree;
        cc.find("rate_tips", this.node).active = bFree;
    },

    async triggerFreeGame() {
        this._bottomScript.ShowBtnsByState("moveing_1");
        cc.vv.AudioManager.playEff("games/WestCowboy/", "music_ChilliFiesta_scatterTrigger", true);

        let logo = cc.find("ChilliFiesta_logo", this.node.parent);
        logo.getComponent(sp.Skeleton).setAnimation(0, "skill", false);
        logo.getComponent(sp.Skeleton).addAnimation(0, "idle", true);

        for (let i = 0; i < this._gameInfo.resultCards.length; i++) {
            let card = this._gameInfo.resultCards[i];
            if (card === this._cfg.scatterId) {
                let symbol = this.GetSymbolByIdx(i + 1);
                if (symbol) {
                    symbol.playWinAnimation();
                }
            }
        }

        // cc.vv.AudioManager.playEff("games/StoneAgedTreasure/", "bell", true);

        await cc.vv.gameData.awaitTime(2);

        await this.popFreeDialog(this._gameInfo.extraFreeInfo);

        this.cutSceneChili();

        await cc.vv.gameData.awaitTime(1);

        cc.find("free_dialog/common_enter_node", this.node.parent).active = false;
        cc.find("free_dialog", this.node.parent).active = false;
        this.ShowGameview(true);

        // 触发免费游戏
        await cc.vv.gameData.awaitTime(2);

        Global.SlotsSoundMgr.stopBgm();
        Global.SlotsSoundMgr.playBgm("music_ChilliFiesta_freeSpinBgSound");
        this.CanDoNextRound();
    },

    async triggerExitFreeGame() {
        this._bottomScript.ShowBtnsByState("moveing_1");

        await cc.vv.gameData.awaitTime(1);

        await this.popFreeResultDialog();

        this.cutSceneChili();

        await cc.vv.gameData.awaitTime(1);

        this.ShowGameview(false);

        await cc.vv.gameData.awaitTime(1);

        this.ShowBottomWin(cc.vv.gameData.GetGameTotalFreeWin(), cc.vv.gameData.GetGameTotalFreeWin(), true, () => {
            Global.SlotsSoundMgr.stopBgm();
            Global.SlotsSoundMgr.playNormalBgm();
            this.CanDoNextRound();
        });
    },

    popFreeDialog(extraFreeInfo) {
        return new Promise(async (success) => {
            this._enterFreeCallback = success;
            cc.vv.AudioManager.playEff("games/WestCowboy/", "music_ChilliFiesta_freespin_choose", true);
            let free_dialog = cc.find("free_dialog", this.node.parent);
            free_dialog.active = true;

            let dialog = cc.find("common_enter_node", free_dialog);
            dialog.active = true;

            let logo = cc.find("logo", dialog);
            logo.scale = 0;
            cc.tween(logo)
                .to(0.5, {scale: 1}, {easing: "backOut"})
                .start();

            for (let i = 0; i < 3; i++) {
                let node = cc.find("node_" + (i + 1), dialog);
                node.scale = 0;
                node.color = cc.Color.WHITE;
                for (let child of node.children) {
                    child.color = cc.Color.WHITE;
                }
                cc.find("times", node).getComponent(cc.Label).string = extraFreeInfo.options[i].freeCnt;
                for (let j = 0; j < 3; j++) {
                    cc.find("rate_" + (j + 1), node).getComponent(cc.Label).string =
                        "X" + extraFreeInfo.options[i].mults[j];
                }
                cc.tween(node)
                    .delay(0.5 + 0.5 * i)
                    .to(0.5, {scale: 1}, {easing: "backOut"})
                    .delay(1 - i * 0.5)
                    .repeatForever(cc.tween().to(1, {scale: 1.1}).to(1, {scale: 1}))
                    .start();
                node.on(cc.Node.EventType.TOUCH_END, async () => {
                    node.off(cc.Node.EventType.TOUCH_END);
                    dialog.stopAllActions();
                    cc.vv.AudioManager.playEff("games/WestCowboy/", "music_ChilliFiesta_freespin_chooseTimes", true);
                    let req = {rtype: 1, choiceId: i + 1};
                    let result = await cc.vv.gameData.reqSubGame(req);
                    if (result.code === 200 && result.data.rtype === 1) {
                        for (let i = 0; i < 3; i++) {
                            let node = cc.find("free_dialog/common_enter_node/node_" + (i + 1), this.node.parent);
                            node.scale = 1;
                            node.stopAllActions();
                            if (i === result.data.choiceId - 1) {
                                node.scale = 1.2;
                            } else {
                                node.color = cc.Color.GRAY;
                                for (let child of node.children) {
                                    child.color = cc.Color.GRAY;
                                }
                            }
                        }

                        cc.vv.gameData.SetTotalFree(result.data.extraFreeInfo.choiceInfo.freeCnt);
                        cc.vv.gameData.SetFreeTime(result.data.extraFreeInfo.choiceInfo.freeCnt);

                        cc.find("free_tips", this.node).active = true;

                        cc.find("free_tips/curTimes", this.node).getComponent(cc.Label).string = "0";
                        cc.find("free_tips/allTimes", this.node).getComponent(cc.Label).string = result.data.extraFreeInfo.choiceInfo.freeCnt;
                        cc.find("rate_tips", this.node).active = true;
                        cc.find("rate_tips/rate", this.node).getComponent(cc.Label).string = "";

                        await cc.vv.gameData.awaitTime(1);

                        if (this._enterFreeCallback) {
                            this._enterFreeCallback();
                            this._enterFreeCallback = null;
                        }
                    }
                });
            }

            await cc.vv.gameData.awaitTime(2);

            if (cc.vv.gameData.isNeedAutoPlay()) {
                cc.tween(dialog)
                    .delay(cc.vv.gameData.getManualAutoPlayTime())
                    .call(async ()=>{
                        cc.vv.AudioManager.playEff("games/WestCowboy/", "music_ChilliFiesta_freespin_chooseTimes", true);
                        let req = {rtype: 1, choiceId: 1};
                        let result = await cc.vv.gameData.reqSubGame(req);
                        if (result.code === 200 && result.data.rtype === 1) {
                            for (let i = 0; i < 3; i++) {
                                let node = cc.find("free_dialog/common_enter_node/node_" + (i + 1), this.node.parent);
                                node.scale = 1;
                                node.stopAllActions();
                                if (i === result.data.choiceId - 1) {
                                    node.scale = 1.2;
                                } else {
                                    node.color = cc.Color.GRAY;
                                    for (let child of node.children) {
                                        child.color = cc.Color.GRAY;
                                    }
                                }
                            }

                            cc.vv.gameData.SetTotalFree(result.data.extraFreeInfo.choiceInfo.freeCnt);
                            cc.vv.gameData.SetFreeTime(result.data.extraFreeInfo.choiceInfo.freeCnt);

                            cc.find("free_tips", this.node).active = true;

                            cc.find("free_tips/curTimes", this.node).getComponent(cc.Label).string = "0";
                            cc.find("free_tips/allTimes", this.node).getComponent(cc.Label).string = result.data.extraFreeInfo.choiceInfo.freeCnt;
                            cc.find("rate_tips", this.node).active = true;
                            cc.find("rate_tips/rate", this.node).getComponent(cc.Label).string = "";

                            await cc.vv.gameData.awaitTime(1);

                            if (this._enterFreeCallback) {
                                this._enterFreeCallback();
                                this._enterFreeCallback = null;
                            }
                        }
                    })
                    .start();
            }
        });
    },

    popFreeResultDialog() {
        return new Promise(async (success) => {
            cc.vv.AudioManager.playEff("games/WestCowboy/", "music_ChilliFiesta_freespinOver", true);
            let free_dialog = cc.find("free_dialog", this.node.parent);
            free_dialog.active = true;

            let dialog = cc.find("result_node", free_dialog);
            dialog.active = true;

            let bg = cc.find("bg", dialog);
            bg.scale = 0;
            cc.tween(bg)
                .to(0.5, {scale: 1}, {easing: "backOut"})
                .start();

            let coin = cc.find("coin", bg);
            coin.getComponent(cc.Label).string = Global.formatMoney(cc.vv.gameData.GetGameTotalFreeWin());

            let times = cc.find("times", bg);
            times.getComponent(cc.Label).string = cc.vv.gameData.GetTotalFree();

            let btn_collect = cc.find("btn_collect", bg);
            cc.vv.AudioManager.playEff("games/WestCowboy/", "music_ChilliFiesta_collect", true);
            btn_collect.off("click");
            let func = async ()=>{
                btn_collect.off("click");

                cc.tween(bg)
                    .to(0.5, {scale: 0}, {easing: "backIn"})
                    .call(() => {
                        dialog.active = false;
                        free_dialog.active = false;
                        success();
                    })
                    .start()
            }
            cc.vv.gameData.checkAutoPlay(btn_collect, func);
            btn_collect.on("click", async () => {
                btn_collect.stopAllActions();
                await func();
            });
        })
    },


    //根据服务端序号获取本地的symbol
    // GetSymbolByIdx: function (idx) {
    //     this._super(idx);
    // },
});