/**
 * @description
 */

cc.Class({
    extends: require("LMSlots_Symbol_Base"),

    properties: {},

    // LIFE-CYCLE CALLBACKS:

    // onLoad () {},
    Init: function (idx, node) {
        this._super(idx, node);
    },

    initSymbolType(type){
        this._bonusType = type;
    },


    StartMove: function () {
        this._super();
        let lajiao = cc.find("symbol_3/lajiao", this.node);
        if (lajiao) {
            lajiao.angle = 0;
            lajiao.stopAllActions();
        }
    },

    //显示随机符号
    ShowRandomSymbol: function () {
        this._super();

        this.showCoin();
    },

    ShowById(id, data) {
        this._super(id, data);
        this.showCoin();
    },

    playBonusStopAnimation() {
        if (this._id === cc.vv.gameData.getGameCfg().bonusId && this._showNode) {
            cc.tween(this._showNode)
                .repeatForever(cc.tween().to(0.5, {scale: 1.1}).to(0.5, {scale: 1}))
                .start();
        }
    },

    playBonusTriggerAnimation() {
        if (this._id === cc.vv.gameData.getGameCfg().bonusId && this._showNode) {
            this._showNode.scale = 1;
            this._showNode.stopAllActions();

            this._showNode.getComponent(cc.Animation).play("bonus_red_chufa");
            let lajiao = cc.find("lajiao", this._showNode);
            if (lajiao) {
                cc.tween(lajiao)
                    .repeatForever(cc.tween().by(3, {angle: -720}, {easing: "backInOut"}))
                    .start();
            }
        }
    },

    playBonusGenerateAnimation() {
        if (this._id === cc.vv.gameData.getGameCfg().bonusId && this._showNode) {
            let coin = cc.find("coin", this.node);
            let jackpot = cc.find("jackpot", this.node);
            let node = coin;
            if (coin && jackpot) {
                if (this._data) {
                    if (this._data.coin > 0) {
                        node = coin;
                    } else if (this._data.jackpot) {
                        node = jackpot;
                    }
                }
            }
            node.scale = 0;
            cc.tween(node)
                .to(0.5, {scale: 1}, {easing: "backOut"})
                .start();
            cc.tween(this._showNode)
                .delay(0.5)
                .repeatForever(cc.tween().to(0.5, {scale: 1.1}).to(0.5, {scale: 1}))
                .start();
        }
    },

    showCoin() {
        let coin = cc.find("coin", this.node);
        let jackpot = cc.find("jackpot", this.node);
        if (coin && jackpot && this._id === cc.vv.gameData.getGameCfg().bonusId) {
            if (this._data) {
                if (this._data.coin > 0) {
                    coin.active = true;
                    coin.getComponent(cc.Label).string = Global.formatNumShort(this._data.coin, 0);
                } else if (this._data.jackpot) {
                    jackpot.active = true;
                    let atlas = cc.vv.gameData.GetAtlasByName("ChilliFiesta2");
                    let names = ["mini", "minor", "major", "grand"];
                    jackpot.getComponent(cc.Sprite).spriteFrame =
                        atlas.getSpriteFrame("ChilliFiesta-Common-ChiliFiesta_tanban_" + names[this._data.jackpot.id - 1]);
                } else if (this._data.baseCoin) {
                    coin.active = false;
                    jackpot.active = false;

                    let atlas = cc.vv.gameData.GetAtlasByName("ChilliFiesta3");
                    cc.find("lajiao", this._showNode).getComponent(cc.Sprite).spriteFrame =
                        atlas.getSpriteFrame("Symbol-ChilliFiesta_lajiao_gold");
                }
            } else {
                coin.active = true;
                let randomRate = [0.25, 0.5, 0.75, 1, 2, 5, 10];
                let randomCoin = cc.vv.gameData.GetTotalBet() * randomRate[Math.floor(Math.random() * randomRate.length)];
                coin.getComponent(cc.Label).string = Global.formatNumShort(randomCoin, 0);
            }
        } else {
            coin.active = false;
            jackpot.active = false;
        }
    },

    playBonusCoinAnimation(baseCoin) {
        if (this._id === cc.vv.gameData.getGameCfg().bonusId && this._showNode) {
            let coin = cc.find("coin", this.node);
            coin.active = true;
            coin.getComponent(cc.Label).string = Global.formatNumShort(baseCoin, 0);
            coin.scale = 0;
            cc.tween(coin)
                .to(0.5, {scale: 1}, {easing: "backOut"})
                .start();
        }
    },
});